type Mode = "create" | "detail" | "edit" | "delete" | "calendar" | "review" | "publishing" | "optimizer" | "clusters" | "analytics" | "brand" | "linking"

type SectionProps = {eyebrow:string;title:string;description?:string;action?:React.ReactNode}
function SectionHeading({eyebrow,title,description,action}:SectionProps){return <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="text-[11px] font-extrabold uppercase tracking-[0.2em] text-sky-700">{eyebrow}</p><h2 className="mt-2 text-2xl font-black tracking-[-0.025em] text-slate-950">{title}</h2>{description?<p className="mt-2 max-w-3xl text-sm font-medium leading-6 text-slate-500">{description}</p>:null}</div>{action?<div className="flex flex-wrap gap-2">{action}</div>:null}</div>}

const modeConfig: Record<Mode,{active:string;eyebrow:string;title:string;description:string}> = {
  create:{active:"",eyebrow:"Studio de briefing",title:"Créer une initiative éditoriale",description:"Cadrez l’intention, l’audience, la gouvernance, les responsabilités et les exigences SEO avant d’engager la production."},
  detail:{active:"",eyebrow:"Dossier éditorial",title:"Article & performance organique",description:"Une vue consolidée de la stratégie, de la qualité, de la production, des échéances et de la préparation à la publication."},
  edit:{active:"",eyebrow:"Studio de production",title:"Modifier l’article",description:"Travaillez le contenu, les métadonnées, le maillage et les responsabilités depuis une surface éditoriale structurée."},
  delete:{active:"",eyebrow:"Action sensible",title:"Supprimer l’article",description:"Confirmez la suppression de l’article et de ses tâches associées dans le stockage actuel du module."},
  calendar:{active:"/market-os/seo-blog-workspace/calendar",eyebrow:"Planification éditoriale",title:"Calendrier de production SEO",description:"Visualisez la cadence, les dates programmées et les espaces disponibles pour les prochaines initiatives."},
  review:{active:"/market-os/seo-blog-workspace/review",eyebrow:"Quality Gate",title:"Bureau de validation éditoriale",description:"Arbitrez les brouillons et contenus en validation avec une lecture claire des scores, écarts et responsabilités."},
  publishing:{active:"/market-os/seo-blog-workspace/publishing",eyebrow:"Publication Control",title:"Préparation à la publication",description:"Contrôlez les seuils existants, la programmation et l’enregistrement du statut éditorial sans prétendre à un déploiement externe."},
  optimizer:{active:"/market-os/seo-blog-workspace/optimizer",eyebrow:"Quality Intelligence",title:"Optimiseur de portefeuille",description:"Priorisez les écarts SEO, marque et lisibilité à partir des valeurs réellement enregistrées dans le workspace."},
  clusters:{active:"/market-os/seo-blog-workspace/topic-clusters",eyebrow:"Content Authority",title:"Commandement des clusters",description:"Structurez les piliers, la couverture éditoriale et les objectifs organiques par intention de recherche."},
  analytics:{active:"/market-os/seo-blog-workspace/analytics",eyebrow:"Organic Performance",title:"Performance organique enregistrée",description:"Comparez les positions, impressions, clics et conversions contenus dans les dossiers actuels."},
  brand:{active:"/market-os/seo-blog-workspace/brand-governance",eyebrow:"Institutional Governance",title:"Gouvernance éditoriale ANGELCARE",description:"Protégez la marque, la sensibilité médicale, la qualité éditoriale et la discipline de conversion."},
  linking:{active:"/market-os/seo-blog-workspace/linking",eyebrow:"Authority Flow",title:"Plan de maillage interne",description:"Organisez les liens enregistrés entre les contenus sans prétendre à un crawl ou à une modification automatique du site public."},
}

const emptyArticle: SeoArticle = {id:"",title:"",slug:"",status:"idea",priority:"Medium",channel:"Blog",owner:"",reviewer:"",cluster:"",primaryKeyword:"",secondaryKeywords:[],intent:"informational",audience:"",objective:"",metaTitle:"",metaDescription:"",h1:"",outline:[],body:"",internalLinks:[],externalLinks:[],brandScore:75,seoScore:70,readability:80,dueDate:todayISO(7),scheduledDate:todayISO(14),createdAt:"",updatedAt:"",notes:"",canonicalUrl:"",wordCount:0,impressions:0,clicks:0,rank:99,conversions:0}

function SubpageShell({mode,children,actions}:{mode:Mode;children:React.ReactNode;actions?:React.ReactNode}){
  const config=modeConfig[mode]
  return <Shell><main className="mx-auto max-w-[1780px] space-y-5 p-4 lg:p-7 xl:p-8"><PageIntro eyebrow={config.eyebrow} title={config.title} description={config.description} actions={<><Button href="/market-os/seo-blog-workspace"><ArrowLeft className="h-4 w-4"/> Centre de commande</Button>{mode!=="create"?<Button href="/market-os/seo-blog-workspace/create" kind="primary"><FilePlus2 className="h-4 w-4"/> Créer</Button>:null}{actions}</>}/><WorkspaceNav active={config.active}/><WorkspaceTruthNotice/>{children}</main></Shell>
}

function FormSection({icon:Icon,title,description,children}:{icon:React.ComponentType<{className?:string}>;title:string;description:string;children:React.ReactNode}){
  return <Panel className="overflow-hidden"><div className="border-b border-slate-100 bg-slate-50/70 p-5"><div className="flex gap-3"><div className="rounded-2xl bg-white p-3 text-sky-700 shadow-sm"><Icon className="h-5 w-5"/></div><div><h3 className="text-lg font-black text-slate-950">{title}</h3><p className="mt-1 text-xs font-medium leading-5 text-slate-500">{description}</p></div></div></div><div className="p-5">{children}</div></Panel>
}

function ArticleForm({initial,onSave,submitLabel}:{initial?:SeoArticle;onSave:(article:SeoArticle)=>void;submitLabel:string}){
  const [form,setForm]=React.useState<SeoArticle>(initial||emptyArticle)
  const set=<K extends keyof SeoArticle>(key:K,value:SeoArticle[K])=>setForm(current=>({...current,[key]:value}))
  const textArray=(value:string[])=>value.join("\n")
  const parseLines=(value:string)=>value.split(/\n|,/).map(item=>item.trim()).filter(Boolean)
  const handleSave=()=>{const now=new Date().toISOString();const normalized:SeoArticle={...form,id:form.id||uid("seo"),slug:form.slug||form.title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""),createdAt:form.createdAt||now,updatedAt:now,wordCount:form.body.trim()?form.body.trim().split(/\s+/).length:form.wordCount};onSave(normalized)}
  const readiness=articleReadiness(form,[],[])
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="space-y-5"><FormSection icon={Target} title="Cadrage stratégique" description="Définissez la raison d’être du contenu avant de travailler sa forme."><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><Field label="Titre de l’article" required hint="Titre de travail visible dans le portefeuille."><input className={inputClass} value={form.title} onChange={(e:any)=>set("title",e.target.value)}/></Field><Field label="Slug" hint="Conservé tel qu’enregistré ou généré au moment de la sauvegarde."><input className={inputClass} value={form.slug} onChange={(e:any)=>set("slug",e.target.value)}/></Field><Field label="Canal"><select className={inputClass} value={form.channel} onChange={(e:any)=>set("channel",e.target.value as SeoArticle["channel"])}>{channels.map(channel=><option key={channel}>{channel}</option>)}</select></Field><Field label="Audience cible"><input className={inputClass} value={form.audience} onChange={(e:any)=>set("audience",e.target.value)}/></Field><Field label="Objectif commercial"><input className={inputClass} value={form.objective} onChange={(e:any)=>set("objective",e.target.value)}/></Field><Field label="Intention de recherche"><select className={inputClass} value={form.intent} onChange={(e:any)=>set("intent",e.target.value as SeoArticle["intent"])}>{intents.map(intent=><option key={intent} value={intent}>{label(intent)}</option>)}</select></Field><Field label="Cluster thématique"><input className={inputClass} value={form.cluster} onChange={(e:any)=>set("cluster",e.target.value)}/></Field><Field label="Responsable"><input className={inputClass} value={form.owner} onChange={(e:any)=>set("owner",e.target.value)}/></Field><Field label="Validateur"><input className={inputClass} value={form.reviewer} onChange={(e:any)=>set("reviewer",e.target.value)}/></Field></div></FormSection><FormSection icon={Search} title="Fondations SEO" description="Structurez les métadonnées et l’orientation sémantique déjà prises en charge par le modèle actuel."><div className="grid gap-4 md:grid-cols-2"><Field label="Mot-clé principal" required><input className={inputClass} value={form.primaryKeyword} onChange={(e:any)=>set("primaryKeyword",e.target.value)}/></Field><Field label="Mots-clés secondaires" hint="Un mot-clé par ligne."><textarea className={inputClass} rows={4} value={textArray(form.secondaryKeywords)} onChange={(e:any)=>set("secondaryKeywords",parseLines(e.target.value))}/></Field><Field label="Meta title" hint={`${form.metaTitle.length}/65 caractères`}><input className={inputClass} value={form.metaTitle} onChange={(e:any)=>set("metaTitle",e.target.value)}/></Field><Field label="Meta description" hint={`${form.metaDescription.length}/160 caractères`}><textarea className={inputClass} rows={4} value={form.metaDescription} onChange={(e:any)=>set("metaDescription",e.target.value)}/></Field><Field label="H1"><input className={inputClass} value={form.h1} onChange={(e:any)=>set("h1",e.target.value)}/></Field><Field label="URL canonique"><input className={inputClass} value={form.canonicalUrl} onChange={(e:any)=>set("canonicalUrl",e.target.value)}/></Field></div></FormSection><FormSection icon={PenLine} title="Production éditoriale" description="Composez l’architecture, le corps et les références sans distraction."><div className="grid gap-4"><Field label="Plan de l’article" hint="Une section par ligne."><textarea className={inputClass} rows={7} value={textArray(form.outline)} onChange={(e:any)=>set("outline",parseLines(e.target.value))}/></Field><Field label="Corps de l’article"><textarea className={cx(inputClass,"min-h-[360px] resize-y font-medium leading-7")} value={form.body} onChange={(e:any)=>set("body",e.target.value)}/></Field><div className="grid gap-4 md:grid-cols-2"><Field label="Liens internes" hint="Un lien par ligne."><textarea className={inputClass} rows={5} value={textArray(form.internalLinks)} onChange={(e:any)=>set("internalLinks",parseLines(e.target.value))}/></Field><Field label="Liens externes" hint="Un lien par ligne."><textarea className={inputClass} rows={5} value={textArray(form.externalLinks)} onChange={(e:any)=>set("externalLinks",parseLines(e.target.value))}/></Field></div></div></FormSection><FormSection icon={ClipboardCheck} title="Pilotage & échéances" description="Rendez la responsabilité, le statut et la qualité visibles avant sauvegarde."><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><Field label="Statut"><select className={inputClass} value={form.status} onChange={(e:any)=>set("status",e.target.value as SeoStatus)}>{[...statuses,"archived" as SeoStatus].map(status=><option key={status} value={status}>{label(status)}</option>)}</select></Field><Field label="Priorité"><select className={inputClass} value={form.priority} onChange={(e:any)=>set("priority",e.target.value as SeoArticle["priority"])}>{priorities.map(priority=><option key={priority}>{priority}</option>)}</select></Field><Field label="Échéance"><input type="date" className={inputClass} value={form.dueDate} onChange={(e:any)=>set("dueDate",e.target.value)}/></Field><Field label="Date programmée"><input type="date" className={inputClass} value={form.scheduledDate} onChange={(e:any)=>set("scheduledDate",e.target.value)}/></Field><Field label="Score SEO"><input type="number" min={0} max={100} className={inputClass} value={form.seoScore} onChange={(e:any)=>set("seoScore",Number(e.target.value))}/></Field><Field label="Score marque"><input type="number" min={0} max={100} className={inputClass} value={form.brandScore} onChange={(e:any)=>set("brandScore",Number(e.target.value))}/></Field><Field label="Lisibilité"><input type="number" min={0} max={100} className={inputClass} value={form.readability} onChange={(e:any)=>set("readability",Number(e.target.value))}/></Field><Field label="Notes internes"><textarea className={inputClass} rows={4} value={form.notes} onChange={(e:any)=>set("notes",e.target.value)}/></Field></div></FormSection><Panel className="sticky bottom-4 z-20 flex flex-col gap-3 border-slate-300 p-4 shadow-2xl sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-black text-slate-950">Prêt à enregistrer les modifications</p><p className="mt-1 text-xs font-medium text-slate-500">La sauvegarde conserve le schéma et la clé de stockage existants.</p></div><div className="flex gap-2"><Button href="/market-os/seo-blog-workspace">Annuler</Button><Button onClick={handleSave} kind="primary"><Save className="h-4 w-4"/> {submitLabel}</Button></div></Panel></div><aside className="space-y-4 xl:sticky xl:top-5 xl:self-start"><Panel className="p-5"><p className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-sky-700">Diagnostic instantané</p><h3 className="mt-2 text-xl font-black text-slate-950">Préparation du dossier</h3><div className="mt-5"><div className="flex items-end justify-between"><span className="text-sm font-bold text-slate-500">Score indicatif</span><span className="text-3xl font-black text-slate-950">{readiness}%</span></div><Meter value={readiness} tone={readiness>=80?"emerald":readiness>=60?"amber":"red"}/></div><div className="mt-5 space-y-2"><GateLine ok={Boolean(form.primaryKeyword)} label="Mot-clé principal" detail={form.primaryKeyword||"À définir"}/><GateLine ok={form.metaTitle.length>=35&&form.metaTitle.length<=65} label="Meta title" detail={`${form.metaTitle.length} caractères enregistrés`}/><GateLine ok={form.metaDescription.length>=90&&form.metaDescription.length<=160} label="Meta description" detail={`${form.metaDescription.length} caractères enregistrés`}/><GateLine ok={form.outline.length>=4} label="Plan éditorial" detail={`${form.outline.length} sections`}/><GateLine ok={form.internalLinks.length>=2} label="Maillage interne" detail={`${form.internalLinks.length} liens`}/></div></Panel><Panel className="p-5"><div className="flex items-center gap-3"><ShieldCheck className="h-5 w-5 text-emerald-600"/><h3 className="font-black text-slate-950">Vérité opérationnelle</h3></div><p className="mt-3 text-xs font-medium leading-6 text-slate-500">Les scores restent des valeurs du modèle actuel. Cette surface ne prétend ni analyser le SERP, ni publier sur un CMS, ni synchroniser Google Analytics.</p></Panel></aside></div>
}

function ArticleNotFound({articleId}:{articleId?:string}){return <SubpageShell mode="detail"><EmptyState title="Article introuvable" description={`Aucun article enregistré ne correspond à l’identifiant ${articleId||"demandé"}. Le portefeuille existant reste intact.`} action={<Button href="/market-os/seo-blog-workspace">Retour au portefeuille</Button>}/></SubpageShell>}

function DetailWorkspace({article,store,advance}:{article:SeoArticle;store:SeoStore;advance:()=>void}){
  const readiness=articleReadiness(article,store.tasks,store.rules)
  const articleTasks=store.tasks.filter(task=>task.articleId===article.id)
  const activeRules=store.rules.filter(rule=>rule.active)
  const gateStatus=canPublish(article,store.tasks,store.rules)
  return <SubpageShell mode="detail" actions={<><Button href={`/market-os/seo-blog-workspace/${article.id}/edit`} kind="primary"><PenLine className="h-4 w-4"/> Modifier</Button><Button onClick={advance} kind="dark">Étape suivante <ArrowRight className="h-4 w-4"/></Button></>}><section className="rounded-[2rem] border border-slate-200 bg-white p-5 shadow-sm lg:p-7"><div className="flex flex-col gap-6 xl:flex-row xl:items-start xl:justify-between"><div className="max-w-4xl"><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><PriorityBadge priority={article.priority}/><Badge>{article.channel}</Badge><Badge>{label(article.intent)}</Badge></div><h2 className="mt-5 text-3xl font-black tracking-[-0.03em] text-slate-950 md:text-4xl">{article.title}</h2><p className="mt-3 max-w-3xl text-sm font-medium leading-7 text-slate-600">{article.objective||"Objectif commercial à préciser."}</p><div className="mt-5 flex flex-wrap gap-x-6 gap-y-2 text-xs font-semibold text-slate-500"><span className="inline-flex items-center gap-2"><Users2 className="h-4 w-4 text-sky-600"/> {article.owner||"Responsable à définir"}</span><span className="inline-flex items-center gap-2"><BookOpenCheck className="h-4 w-4 text-violet-600"/> {article.reviewer||"Validateur à définir"}</span><span className="inline-flex items-center gap-2"><Clock3 className="h-4 w-4 text-amber-600"/> Échéance {formatDate(article.dueDate)}</span><span className="inline-flex items-center gap-2"><Network className="h-4 w-4 text-emerald-600"/> {article.cluster||"Cluster à définir"}</span></div></div><div className="grid grid-cols-3 gap-2"><ScorePill label="SEO" value={article.seoScore}/><ScorePill label="Marque" value={article.brandScore}/><ScorePill label="Lisibilité" value={article.readability}/></div></div></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1.2fr)_minmax(340px,.55fr)]"><div className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Brief stratégique" title="Ciblage & positionnement"/><div className="mt-5 grid gap-3 md:grid-cols-2"><InfoCard label="Mot-clé principal" value={article.primaryKeyword||"Non défini"}/><InfoCard label="Audience" value={article.audience||"Non définie"}/><InfoCard label="Intention" value={label(article.intent)}/><InfoCard label="Cluster" value={article.cluster||"Non défini"}/></div>{article.secondaryKeywords.length?<div className="mt-4 flex flex-wrap gap-2">{article.secondaryKeywords.map(keyword=><Badge key={keyword}>{keyword}</Badge>)}</div>:null}</Panel><Panel className="p-5"><SectionHeading eyebrow="Architecture éditoriale" title={article.h1||"Structure du contenu"} description={article.metaDescription||"Aucune meta description enregistrée."}/><div className="mt-5 grid gap-5 lg:grid-cols-[.65fr_1.35fr]"><div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4"><p className="text-[11px] font-extrabold uppercase tracking-[0.14em] text-slate-500">Plan</p>{article.outline.length?<ol className="mt-4 space-y-3">{article.outline.map((item,index)=><li key={`${item}-${index}`} className="flex gap-3 text-sm font-semibold leading-6 text-slate-700"><span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-white text-[10px] font-black text-sky-700 shadow-sm">{index+1}</span>{item}</li>)}</ol>:<p className="mt-3 text-sm text-slate-500">Plan non renseigné.</p>}</div><div className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-[11px] font-extrabold uppercase tracking-[0.14em] text-slate-500">Corps enregistré</p><p className="mt-4 whitespace-pre-wrap text-sm font-medium leading-7 text-slate-700">{article.body||"Aucun corps éditorial enregistré."}</p></div></div></Panel><Panel className="p-5"><SectionHeading eyebrow="Liens & références" title="Maillage du contenu"/><div className="mt-5 grid gap-4 md:grid-cols-2"><LinkList title="Liens internes" links={article.internalLinks}/><LinkList title="Liens externes" links={article.externalLinks}/></div></Panel><Panel className="p-5"><SectionHeading eyebrow="Exécution" title="Tâches associées"/><div className="mt-5 space-y-3">{articleTasks.length?articleTasks.map(task=><div key={task.id} className="flex flex-col gap-3 rounded-2xl border border-slate-200 p-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap gap-2"><Badge kind={task.status==="blocked"?"danger":task.status==="done"?"success":"default"}>{label(task.status)}</Badge><Badge>{task.owner}</Badge></div><p className="mt-3 text-sm font-black text-slate-950">{task.title}</p><p className="mt-1 text-xs font-medium text-slate-500">{task.note}</p></div><p className="text-xs font-bold text-slate-500">{formatDate(task.dueDate)}</p></div>):<EmptyState title="Aucune tâche associée" description="Le dossier ne contient actuellement aucune tâche éditoriale ouverte."/>}</div></Panel></div><aside className="space-y-5"><Panel className="p-5"><p className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-sky-700">Publish Gate</p><div className="mt-2 flex items-end justify-between"><h3 className="text-xl font-black text-slate-950">Préparation</h3><span className="text-3xl font-black text-slate-950">{readiness}%</span></div><div className="mt-4"><Meter value={readiness} tone={readiness>=80?"emerald":readiness>=60?"amber":"red"}/></div><div className="mt-5 space-y-2"><GateLine ok={article.status==="approved"} label="Statut approuvé" detail={`Statut actuel : ${label(article.status)}`}/><GateLine ok={readiness>=80} label="Préparation ≥ 80" detail={`Valeur actuelle : ${readiness}%`}/><GateLine ok={article.seoScore>=75} label="SEO ≥ 75" detail={`Valeur actuelle : ${article.seoScore}`}/><GateLine ok={article.brandScore>=75} label="Marque ≥ 75" detail={`Valeur actuelle : ${article.brandScore}`}/></div><div className={cx("mt-5 rounded-2xl border p-4 text-sm font-extrabold",gateStatus?"border-emerald-200 bg-emerald-50 text-emerald-800":"border-amber-200 bg-amber-50 text-amber-800")}>{gateStatus?"Le dossier satisfait les seuils actuels.":"Le dossier nécessite encore une intervention."}</div></Panel><Panel className="p-5"><SectionHeading eyebrow="Gouvernance" title="Règles actives"/><div className="mt-4 space-y-3">{activeRules.map(rule=><div key={rule.id} className="rounded-2xl border border-slate-200 p-3"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-emerald-600"/><div><p className="text-sm font-black text-slate-950">{rule.title}</p><p className="mt-1 text-xs font-medium leading-5 text-slate-500">{rule.description}</p></div></div></div>)}</div></Panel><Panel className="p-5"><SectionHeading eyebrow="Dates" title="Repères du dossier"/><dl className="mt-4 space-y-3 text-sm"><DateLine label="Créé" value={formatDateTime(article.createdAt)}/><DateLine label="Mis à jour" value={formatDateTime(article.updatedAt)}/><DateLine label="Programmé" value={formatDate(article.scheduledDate)}/><DateLine label="Publié" value={formatDate(article.publishedDate)}/></dl></Panel><Button href={`/market-os/seo-blog-workspace/${article.id}/delete`} kind="danger" className="w-full"><Trash2 className="h-4 w-4"/> Supprimer le dossier</Button></aside></div></SubpageShell>
}

function InfoCard({label:cardLabel,value}:{label:string;value:string}){return <div className="rounded-2xl border border-slate-200 bg-slate-50/60 p-4"><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-slate-500">{cardLabel}</p><p className="mt-2 text-sm font-black leading-6 text-slate-900">{value}</p></div>}
function DateLine({label:dateLabel,value}:{label:string;value:string}){return <div className="flex items-center justify-between gap-4 border-b border-slate-100 pb-3 last:border-0 last:pb-0"><dt className="font-semibold text-slate-500">{dateLabel}</dt><dd className="text-right font-black text-slate-900">{value}</dd></div>}
function LinkList({title,links}:{title:string;links:string[]}){return <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4"><p className="text-[11px] font-extrabold uppercase tracking-[0.14em] text-slate-500">{title}</p>{links.length?<div className="mt-3 space-y-2">{links.map((link,index)=><div key={`${link}-${index}`} className="flex items-center gap-2 rounded-xl bg-white px-3 py-2 text-xs font-semibold text-slate-700"><Link2 className="h-3.5 w-3.5 text-sky-600"/><span className="truncate">{link}</span></div>)}</div>:<p className="mt-3 text-sm font-medium text-slate-400">Aucun lien enregistré.</p>}</div>}

function DeleteWorkspace({article,onDelete}:{article:SeoArticle;onDelete:()=>void}){return <SubpageShell mode="delete"><div className="mx-auto max-w-4xl"><Panel className="overflow-hidden border-red-200"><div className="bg-red-50 p-6"><div className="flex items-start gap-4"><div className="rounded-2xl bg-white p-3 text-red-600 shadow-sm"><ShieldAlert className="h-7 w-7"/></div><div><Badge kind="danger">Action irréversible dans le store actuel</Badge><h2 className="mt-4 text-3xl font-black tracking-tight text-slate-950">Confirmer la suppression</h2><p className="mt-3 text-sm font-medium leading-7 text-slate-600">Cette action supprimera l’article et les tâches qui lui sont associées dans le stockage local existant.</p></div></div></div><div className="p-6"><div className="rounded-2xl border border-slate-200 bg-slate-50 p-5"><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><PriorityBadge priority={article.priority}/></div><h3 className="mt-4 text-xl font-black text-slate-950">{article.title}</h3><p className="mt-2 text-sm font-medium text-slate-500">{article.primaryKeyword} · {article.owner}</p></div><div className="mt-6 space-y-2"><GateLine ok={false} label="Article supprimé" detail="Le dossier ne sera plus disponible dans ce navigateur."/><GateLine ok={false} label="Tâches associées supprimées" detail="Les tâches portant cet identifiant d’article seront également retirées."/><GateLine ok={true} label="Autres dossiers protégés" detail="Les autres articles, clusters, règles et logs ne sont pas ciblés."/></div><div className="mt-7 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><Button href={`/market-os/seo-blog-workspace/${article.id}`}>Annuler et revenir au dossier</Button><Button onClick={onDelete} kind="danger"><Trash2 className="h-4 w-4"/> Confirmer la suppression</Button></div></div></Panel></div></SubpageShell>}

function CalendarWorkspace({store,onDate}:{store:SeoStore;onDate:(iso:string)=>void}){
  const [cursor,setCursor]=React.useState(()=>new Date())
  const year=cursor.getFullYear(); const month=cursor.getMonth(); const first=(new Date(year,month,1).getDay()+6)%7; const days=new Date(year,month+1,0).getDate(); const cells=Array.from({length:42},(_,index)=>{const day=index-first+1;const date=new Date(year,month,day);return {index,day,inMonth:day>=1&&day<=days,iso:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`}})
  const monthArticles=store.articles.filter(article=>article.scheduledDate.startsWith(`${year}-${String(month+1).padStart(2,"0")}`))
  return <SubpageShell mode="calendar" actions={<Button href="/market-os/seo-blog-workspace/create" kind="primary"><FilePlus2 className="h-4 w-4"/> Planifier un article</Button>}><section className="grid gap-3 sm:grid-cols-3"><MetricLite label="Articles programmés" value={monthArticles.length} detail="sur le mois affiché"/><MetricLite label="Jours occupés" value={new Set(monthArticles.map(a=>a.scheduledDate)).size} detail="dates avec contenu"/><MetricLite label="Retards visibles" value={store.articles.filter(a=>a.dueDate<todayISO()&&!['published','archived'].includes(a.status)).length} detail="dans le portefeuille" danger/></section><Panel className="p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-sky-700">Calendrier mensuel</p><h2 className="mt-2 text-2xl font-black capitalize text-slate-950">{new Intl.DateTimeFormat("fr-FR",{month:"long",year:"numeric"}).format(cursor)}</h2><p className="mt-2 text-sm font-medium text-slate-500">Sélectionnez une date pour créer le même article programmé que le workflow existant.</p></div><div className="flex gap-2"><Button onClick={()=>setCursor(new Date(year,month-1,1))}>Mois précédent</Button><Button onClick={()=>setCursor(new Date())}>Aujourd’hui</Button><Button onClick={()=>setCursor(new Date(year,month+1,1))}>Mois suivant</Button></div></div><div className="mt-6 grid grid-cols-7 gap-1 text-center text-[10px] font-extrabold uppercase tracking-wide text-slate-400">{["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"].map(day=><div key={day} className="py-2">{day}</div>)}</div><div className="grid grid-cols-7 gap-1">{cells.map(cell=>{const list=store.articles.filter(a=>a.scheduledDate===cell.iso);const isToday=cell.iso===todayISO();return <div key={cell.index} className={cx("min-h-32 rounded-xl border p-2 transition",cell.inMonth?"border-slate-200 bg-white":"border-transparent bg-slate-50/50 text-slate-300",isToday&&"ring-2 ring-sky-500 ring-offset-1")}><button onClick={()=>cell.inMonth&&onDate(cell.iso)} disabled={!cell.inMonth} className="flex h-7 w-7 items-center justify-center rounded-lg text-xs font-black hover:bg-sky-50 hover:text-sky-700">{cell.inMonth?cell.day:""}</button><div className="mt-2 space-y-1.5">{list.map(article=><Link key={article.id} href={`/market-os/seo-blog-workspace/${article.id}`} className={cx("block rounded-lg border px-2 py-1.5 text-[9px] font-extrabold leading-4",article.status==="published"?"border-emerald-200 bg-emerald-50 text-emerald-800":article.status==="approved"||article.status==="scheduled"?"border-sky-200 bg-sky-50 text-sky-800":"border-amber-200 bg-amber-50 text-amber-800")}>{article.title}</Link>)}</div></div>})}</div></Panel></SubpageShell>
}
function MetricLite({label:metricLabel,value,detail,danger=false}:{label:string;value:number;detail:string;danger?:boolean}){return <Panel className="p-5"><p className="text-[10px] font-extrabold uppercase tracking-[0.16em] text-slate-500">{metricLabel}</p><p className={cx("mt-2 text-3xl font-black",danger&&value?"text-red-600":"text-slate-950")}>{value}</p><p className="mt-1 text-xs font-medium text-slate-500">{detail}</p></Panel>}

function ReviewWorkspace({store,approve,revision}:{store:SeoStore;approve:(id:string,title:string)=>void;revision:(id:string,title:string)=>void}){
  const queue=store.articles.filter(article=>["draft","review"].includes(article.status)).sort((a,b)=>(a.priority==="Critical"?-1:1)-(b.priority==="Critical"?-1:1))
  return <SubpageShell mode="review"><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><Panel className="p-5"><SectionHeading eyebrow="File de décision" title={`${queue.length} contenu${queue.length>1?"s":""} à arbitrer`} description="La validation et la demande de révision conservent exactement les transitions existantes."/><div className="mt-5 space-y-4">{queue.map(article=>{const readiness=articleReadiness(article,store.tasks,store.rules);const openTasks=store.tasks.filter(t=>t.articleId===article.id&&t.status!=="done");return <article key={article.id} className="rounded-2xl border border-slate-200 bg-white p-5 transition hover:border-sky-200 hover:shadow-lg hover:shadow-slate-200/60"><div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between"><div className="max-w-3xl"><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><PriorityBadge priority={article.priority}/><Badge>{article.channel}</Badge></div><Link href={`/market-os/seo-blog-workspace/${article.id}`} className="mt-4 block text-xl font-black leading-7 text-slate-950 hover:text-sky-700">{article.title}</Link><p className="mt-2 text-sm font-medium leading-6 text-slate-500">{article.objective||article.notes}</p><div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-xs font-semibold text-slate-500"><span>{article.owner}</span><span>Validation : {article.reviewer}</span><span>Échéance : {formatDate(article.dueDate)}</span><span>{openTasks.length} tâche{openTasks.length>1?"s":""} ouverte{openTasks.length>1?"s":""}</span></div></div><div className="flex flex-wrap gap-2"><ScorePill label="SEO" value={article.seoScore}/><ScorePill label="Marque" value={article.brandScore}/><ScorePill label="Prêt" value={readiness}/></div></div><div className="mt-5 grid gap-4 border-t border-slate-100 pt-5 lg:grid-cols-[1fr_auto]"><div className="grid gap-2 sm:grid-cols-2"><GateLine ok={article.seoScore>=75} label="Seuil SEO" detail={`${article.seoScore}/100`}/><GateLine ok={article.brandScore>=75} label="Seuil marque" detail={`${article.brandScore}/100`}/></div><div className="flex flex-wrap items-end gap-2"><Button href={`/market-os/seo-blog-workspace/${article.id}/edit`}>Ouvrir l’éditeur</Button><Button onClick={()=>revision(article.id,article.title)}>Demander révision</Button><Button onClick={()=>approve(article.id,article.title)} kind="success"><CheckCircle2 className="h-4 w-4"/> Approuver</Button></div></div></article>})}{queue.length===0?<EmptyState title="Aucune décision en attente" description="Aucun article n’est actuellement en rédaction ou en validation." action={<Button href="/market-os/seo-blog-workspace/create" kind="primary">Créer un contenu</Button>}/>:null}</div></Panel><aside className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Discipline de revue" title="Ordre de contrôle"/><ol className="mt-5 space-y-4">{["Confirmer l’intention et l’objectif commercial.","Vérifier les métadonnées et la structure éditoriale.","Contrôler la marque, la sensibilité et le CTA.","Lire les tâches ouvertes et les dépendances.","Approuver ou retourner en rédaction avec une instruction claire."].map((item,index)=><li key={item} className="flex gap-3 text-sm font-medium leading-6 text-slate-600"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-950 text-xs font-black text-white">{index+1}</span>{item}</li>)}</ol></Panel><Panel className="p-5"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 h-5 w-5 text-emerald-600"/><div><h3 className="font-black text-slate-950">Gouvernance active</h3><p className="mt-2 text-xs font-medium leading-6 text-slate-500">{store.rules.filter(rule=>rule.active).length} règle(s) active(s), dont {store.rules.filter(rule=>rule.active&&rule.required).length} obligatoire(s).</p></div></div></Panel></aside></div></SubpageShell>
}

function PublishingWorkspace({store,publish,schedule}:{store:SeoStore;publish:(id:string,title:string)=>void;schedule:(id:string,title:string)=>void}){
  const queue=store.articles.filter(article=>["approved","scheduled"].includes(article.status))
  return <SubpageShell mode="publishing"><div className="rounded-2xl border border-amber-200 bg-amber-50 p-4"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-700"/><div><p className="text-sm font-black text-amber-900">Portée réelle de cette surface</p><p className="mt-1 text-xs font-medium leading-5 text-amber-800">« Enregistrer comme publié » modifie le statut éditorial dans le store actuel. Cette interface ne prétend pas déployer un article sur un CMS ou déclencher une indexation.</p></div></div></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><Panel className="p-5"><SectionHeading eyebrow="File de publication" title={`${queue.length} contenu${queue.length>1?"s":""} approuvé${queue.length>1?"s":""} ou programmé${queue.length>1?"s":""}`} description="Visualisez les seuils existants avant d’enregistrer le prochain statut."/><div className="mt-5 space-y-4">{queue.map(article=>{const readiness=articleReadiness(article,store.tasks,store.rules);const eligible=canPublish(article,store.tasks,store.rules);return <article key={article.id} className="rounded-2xl border border-slate-200 p-5"><div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between"><div><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><PriorityBadge priority={article.priority}/>{eligible?<Badge kind="success">Seuil satisfait</Badge>:<Badge kind="warning">Contrôle requis</Badge>}</div><Link href={`/market-os/seo-blog-workspace/${article.id}`} className="mt-4 block text-xl font-black text-slate-950 hover:text-sky-700">{article.title}</Link><p className="mt-2 text-sm font-medium text-slate-500">Programmation : {formatDate(article.scheduledDate)} · Responsable : {article.owner}</p></div><div className="flex flex-wrap gap-2"><ScorePill label="SEO" value={article.seoScore}/><ScorePill label="Marque" value={article.brandScore}/><ScorePill label="Prêt" value={readiness}/></div></div><div className="mt-5 grid gap-2 border-t border-slate-100 pt-5 md:grid-cols-2 xl:grid-cols-4"><GateLine ok={article.status==="approved"} label="Approuvé" detail={label(article.status)}/><GateLine ok={readiness>=80} label="Préparation" detail={`${readiness}%`}/><GateLine ok={article.seoScore>=75} label="SEO" detail={`${article.seoScore}/100`}/><GateLine ok={article.brandScore>=75} label="Marque" detail={`${article.brandScore}/100`}/></div><div className="mt-5 flex flex-wrap justify-end gap-2"><Button href={`/market-os/seo-blog-workspace/${article.id}`}>Ouvrir le dossier</Button><Button onClick={()=>schedule(article.id,article.title)}><CalendarDays className="h-4 w-4"/> Marquer programmé</Button><Button onClick={()=>publish(article.id,article.title)} kind="success"><CheckCircle2 className="h-4 w-4"/> Enregistrer comme publié</Button></div></article>})}{queue.length===0?<EmptyState title="Aucun contenu dans la file de publication" description="Les articles approuvés ou programmés apparaîtront ici avec leurs contrôles de préparation."/>:null}</div></Panel><aside className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Cadence" title="Prochaines dates"/><div className="mt-4 space-y-3">{[...queue].sort((a,b)=>a.scheduledDate.localeCompare(b.scheduledDate)).slice(0,6).map(article=><Link key={article.id} href={`/market-os/seo-blog-workspace/${article.id}`} className="block rounded-2xl border border-slate-200 p-3 hover:border-sky-200"><p className="text-xs font-black text-slate-950">{formatDate(article.scheduledDate)}</p><p className="mt-1 line-clamp-2 text-xs font-medium leading-5 text-slate-500">{article.title}</p></Link>)}</div></Panel><Panel className="p-5"><div className="flex gap-3"><ShieldCheck className="h-5 w-5 text-sky-600"/><div><h3 className="font-black text-slate-950">Règle de vérité</h3><p className="mt-2 text-xs font-medium leading-6 text-slate-500">Le contrôle affiche la préparation actuelle mais ne remplace pas la décision humaine ni un processus de publication externe.</p></div></div></Panel></aside></div></SubpageShell>
}

function OptimizerWorkspace({store,optimize}:{store:SeoStore;optimize:(id:string,title:string)=>void}){
  const ordered=[...store.articles].sort((a,b)=>(a.seoScore+a.brandScore+a.readability)-(b.seoScore+b.brandScore+b.readability))
  return <SubpageShell mode="optimizer"><div className="rounded-2xl border border-violet-200 bg-violet-50 p-4"><div className="flex gap-3"><Sparkles className="mt-0.5 h-5 w-5 shrink-0 text-violet-700"/><div><p className="text-sm font-black text-violet-950">Optimisation transparente</p><p className="mt-1 text-xs font-medium leading-5 text-violet-800">L’action existante ajuste les scores enregistrés selon la logique actuelle. Elle n’est pas présentée comme une analyse IA, un audit SERP ou une réécriture automatique.</p></div></div></div><Panel className="p-5"><SectionHeading eyebrow="Portefeuille qualité" title="Prioriser les contenus les plus faibles" description="Classement ascendant par combinaison des scores SEO, marque et lisibilité."/><div className="mt-5 grid gap-4 xl:grid-cols-2">{ordered.map(article=>{const readiness=articleReadiness(article,store.tasks,store.rules);const diagnostics=[{label:"Mot-clé principal",ok:Boolean(article.primaryKeyword)},{label:"Meta title 35–65",ok:article.metaTitle.length>=35&&article.metaTitle.length<=65},{label:"Meta description 90–160",ok:article.metaDescription.length>=90&&article.metaDescription.length<=160},{label:"Plan ≥ 4 sections",ok:article.outline.length>=4},{label:"Maillage ≥ 2 liens",ok:article.internalLinks.length>=2}];return <article key={article.id} className="rounded-2xl border border-slate-200 p-5"><div className="flex items-start justify-between gap-4"><div><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><PriorityBadge priority={article.priority}/></div><Link href={`/market-os/seo-blog-workspace/${article.id}`} className="mt-4 block text-lg font-black leading-6 text-slate-950 hover:text-sky-700">{article.title}</Link><p className="mt-2 text-xs font-semibold text-slate-500">{article.primaryKeyword||"Mot-clé principal à définir"}</p></div><div className="rounded-2xl bg-slate-950 px-4 py-3 text-center text-white"><p className="text-[9px] font-extrabold uppercase tracking-wide text-slate-400">Prêt</p><p className="mt-1 text-2xl font-black">{readiness}%</p></div></div><div className="mt-5 grid grid-cols-3 gap-2"><ScorePill label="SEO" value={article.seoScore}/><ScorePill label="Marque" value={article.brandScore}/><ScorePill label="Lecture" value={article.readability}/></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{diagnostics.map(item=><div key={item.label} className={cx("flex items-center gap-2 rounded-xl border px-3 py-2 text-xs font-bold",item.ok?"border-emerald-200 bg-emerald-50 text-emerald-800":"border-amber-200 bg-amber-50 text-amber-800")}>{item.ok?<CheckCircle2 className="h-4 w-4"/>:<AlertTriangle className="h-4 w-4"/>}{item.label}</div>)}</div><div className="mt-5 flex flex-wrap justify-end gap-2"><Button href={`/market-os/seo-blog-workspace/${article.id}/edit`}>Modifier le contenu</Button><Button onClick={()=>optimize(article.id,article.title)} kind="primary"><Sparkles className="h-4 w-4"/> Appliquer l’amélioration existante</Button></div></article>})}</div></Panel></SubpageShell>
}

function ClusterWorkspace({store,toggle}:{store:SeoStore;toggle:(cluster:SeoCluster)=>void}){
  return <SubpageShell mode="clusters"><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricLite label="Clusters" value={store.clusters.length} detail="architectures enregistrées"/><MetricLite label="Actifs" value={store.clusters.filter(c=>c.status==="active").length} detail="en production"/><MetricLite label="En expansion" value={store.clusters.filter(c=>c.status==="expanding").length} detail="couverture à renforcer"/><MetricLite label="Articles rattachés" value={store.articles.filter(a=>store.clusters.some(c=>c.name===a.cluster)).length} detail="dossiers associés"/></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="grid gap-4 md:grid-cols-2">{store.clusters.map(cluster=>{const articles=store.articles.filter(article=>article.cluster===cluster.name);const pillar=store.articles.find(article=>article.slug===cluster.pillar);return <Panel key={cluster.id} className="overflow-hidden"><div className="border-b border-slate-100 bg-slate-50/70 p-5"><div className="flex items-start justify-between gap-4"><div><div className="flex flex-wrap gap-2"><StateBadge status={cluster.status}/><Badge>{label(cluster.intent)}</Badge></div><h2 className="mt-4 text-xl font-black text-slate-950">{cluster.name}</h2><p className="mt-2 text-sm font-medium leading-6 text-slate-500">{cluster.target}</p></div><div className="rounded-2xl bg-white px-4 py-3 text-center shadow-sm"><p className="text-2xl font-black text-slate-950">{articles.length}</p><p className="text-[9px] font-extrabold uppercase tracking-wide text-slate-400">articles</p></div></div></div><div className="p-5"><div className="grid gap-3 sm:grid-cols-2"><InfoCard label="Responsable" value={cluster.owner}/><InfoCard label="Pilier" value={pillar?.title||cluster.pillar||"Non défini"}/></div><div className="mt-4"><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-slate-500">Couverture actuelle</p><div className="mt-3 space-y-2">{articles.length?articles.map(article=><Link key={article.id} href={`/market-os/seo-blog-workspace/${article.id}`} className="flex items-center justify-between gap-3 rounded-xl border border-slate-200 px-3 py-2 text-xs font-bold text-slate-700 hover:border-sky-200 hover:text-sky-700"><span className="truncate">{article.title}</span><StateBadge status={article.status}/></Link>):<p className="rounded-xl border border-dashed border-slate-300 p-4 text-xs font-medium text-slate-400">Aucun article rattaché.</p>}</div></div><div className="mt-5 flex justify-end"><Button onClick={()=>toggle(cluster)}>Basculer le statut actuel</Button></div></div></Panel>})}</div><aside className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Lecture stratégique" title="Gaps de couverture"/><div className="mt-5 space-y-3">{store.clusters.map(cluster=>{const count=store.articles.filter(article=>article.cluster===cluster.name).length;return <div key={cluster.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-center justify-between"><p className="text-sm font-black text-slate-950">{cluster.name}</p><Badge kind={count===0?"danger":count<3?"warning":"success"}>{count} article{count>1?"s":""}</Badge></div><p className="mt-2 text-xs font-medium leading-5 text-slate-500">{count===0?"Cluster sans couverture éditoriale.":count<3?"Couverture initiale à renforcer.":"Couverture structurée enregistrée."}</p></div>})}</div></Panel><Button href="/market-os/seo-blog-workspace/create" kind="primary" className="w-full"><FilePlus2 className="h-4 w-4"/> Créer un article de cluster</Button></aside></div></SubpageShell>
}

function AnalyticsWorkspace({store}:{store:SeoStore}){
  const totals=store.articles.reduce((acc,a)=>({impressions:acc.impressions+a.impressions,clicks:acc.clicks+a.clicks,conversions:acc.conversions+a.conversions}),{impressions:0,clicks:0,conversions:0});const ctr=totals.impressions?totals.clicks/totals.impressions*100:0;const maxImpressions=Math.max(1,...store.articles.map(a=>a.impressions))
  return <SubpageShell mode="analytics"><div className="rounded-2xl border border-sky-200 bg-sky-50 p-4"><div className="flex gap-3"><BarChart3 className="mt-0.5 h-5 w-5 shrink-0 text-sky-700"/><div><p className="text-sm font-black text-sky-950">Origine des données</p><p className="mt-1 text-xs font-medium leading-5 text-sky-800">Les indicateurs proviennent des champs enregistrés dans les articles. Aucune synchronisation Search Console, GA4 ou autre source externe n’est affirmée.</p></div></div></div><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Kpi label="Impressions enregistrées" value={compactNumber(totals.impressions)} icon={TrendingUp}/><Kpi label="Clics enregistrés" value={compactNumber(totals.clicks)} icon={FileSearch}/><Kpi label="Conversions enregistrées" value={compactNumber(totals.conversions)} icon={Target}/><Kpi label="CTR calculé" value={`${ctr.toFixed(1)}%`} icon={Gauge}/></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1.2fr)_minmax(340px,.55fr)]"><Panel className="p-5"><SectionHeading eyebrow="Comparatif article" title="Contribution enregistrée" description="Volume d’impressions comparé article par article."/><div className="mt-6 space-y-5">{[...store.articles].sort((a,b)=>b.impressions-a.impressions).map(article=><div key={article.id}><div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><Link href={`/market-os/seo-blog-workspace/${article.id}`} className="text-sm font-black text-slate-950 hover:text-sky-700">{article.title}</Link><p className="mt-1 text-xs font-medium text-slate-500">Position #{article.rank} · {article.clicks} clics · {article.conversions} conversions</p></div><span className="text-xs font-black text-slate-700">{compactNumber(article.impressions)} impressions</span></div><div className="mt-2 h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-sky-600" style={{width:`${Math.max(5,article.impressions/maxImpressions*100)}%`}}/></div></div>)}</div></Panel><aside className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Priorité performance" title="Pages à reprendre"/><div className="mt-4 space-y-3">{[...store.articles].sort((a,b)=>b.rank-a.rank).map(article=><Link key={article.id} href={`/market-os/seo-blog-workspace/${article.id}`} className="block rounded-2xl border border-slate-200 p-4 hover:border-sky-200"><div className="flex items-center justify-between gap-3"><p className="line-clamp-2 text-sm font-black text-slate-950">{article.title}</p><Badge kind={article.rank>15?"danger":article.rank>10?"warning":"success"}>#{article.rank}</Badge></div><p className="mt-2 text-xs font-medium text-slate-500">{article.clicks} clics · {article.conversions} conversions</p></Link>)}</div></Panel><Panel className="p-5"><SectionHeading eyebrow="Qualité moyenne" title="Scores du portefeuille"/><div className="mt-5 space-y-4"><AverageScore label="SEO" value={average(store.articles.map(a=>a.seoScore))}/><AverageScore label="Marque" value={average(store.articles.map(a=>a.brandScore))}/><AverageScore label="Lisibilité" value={average(store.articles.map(a=>a.readability))}/></div></Panel></aside></div></SubpageShell>
}
function Kpi({label:kpiLabel,value,icon:Icon}:{label:string;value:string;icon:React.ComponentType<{className?:string}>}){return <Panel className="p-5"><div className="flex items-start justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.16em] text-slate-500">{kpiLabel}</p><p className="mt-3 text-3xl font-black text-slate-950">{value}</p></div><div className="rounded-2xl bg-sky-50 p-3 text-sky-700"><Icon className="h-5 w-5"/></div></div></Panel>}
function average(values:number[]){return values.length?Math.round(values.reduce((sum,value)=>sum+value,0)/values.length):0}
function AverageScore({label:scoreLabel,value}:{label:string;value:number}){return <div><div className="flex items-center justify-between text-xs font-bold"><span className="text-slate-500">{scoreLabel}</span><span className="text-slate-950">{value}%</span></div><div className="mt-2"><Meter value={value} tone={value>=80?"emerald":value>=70?"amber":"red"}/></div></div>}

function BrandWorkspace({store,toggle}:{store:SeoStore;toggle:(rule:SeoRule)=>void}){
  const categoryLabels:Record<SeoRule["category"],string>={brand:"Marque",technical:"SEO technique",medical:"Sensibilité médicale",conversion:"Conversion",editorial:"Qualité éditoriale"}
  return <SubpageShell mode="brand"><section className="grid gap-3 sm:grid-cols-3"><MetricLite label="Règles actives" value={store.rules.filter(rule=>rule.active).length} detail="gouvernance appliquée"/><MetricLite label="Obligatoires" value={store.rules.filter(rule=>rule.active&&rule.required).length} detail="exigences prioritaires"/><MetricLite label="Catégories" value={new Set(store.rules.map(rule=>rule.category)).size} detail="domaines de contrôle"/></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><Panel className="p-5"><SectionHeading eyebrow="Référentiel éditorial" title="Règles de gouvernance" description="L’activation et la désactivation conservent le comportement existant du store."/><div className="mt-5 space-y-4">{store.rules.map(rule=><article key={rule.id} className={cx("rounded-2xl border p-5",rule.active?"border-emerald-200 bg-emerald-50/30":"border-slate-200 bg-slate-50/60")}><div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div className="max-w-3xl"><div className="flex flex-wrap gap-2"><Badge kind={rule.active?"success":"default"}>{rule.active?"Active":"Inactive"}</Badge><Badge>{categoryLabels[rule.category]}</Badge>{rule.required?<Badge kind="danger">Obligatoire</Badge>:<Badge>Conseil</Badge>}</div><h3 className="mt-4 text-lg font-black text-slate-950">{rule.title}</h3><p className="mt-2 text-sm font-medium leading-7 text-slate-600">{rule.description}</p></div><Button onClick={()=>toggle(rule)} kind={rule.active?"secondary":"success"}>{rule.active?"Désactiver":"Activer"}</Button></div></article>)}</div></Panel><aside className="space-y-5"><Panel className="p-5"><SectionHeading eyebrow="Safeguards ANGELCARE" title="Points non négociables"/><div className="mt-5 space-y-3">{[{title:"Sécurité médicale",text:"Ne pas promettre de diagnostic, traitement ou garantie clinique."},{title:"CTA premium",text:"Orienter le lecteur vers une prochaine étape qualifiée et responsable."},{title:"Pertinence locale",text:"Ancrer le contenu dans le Maroc lorsque cela apporte une vraie valeur."}].map(item=><div key={item.title} className="rounded-2xl border border-slate-200 p-4"><div className="flex gap-3"><ShieldCheck className="mt-0.5 h-5 w-5 shrink-0 text-emerald-600"/><div><p className="text-sm font-black text-slate-950">{item.title}</p><p className="mt-1 text-xs font-medium leading-5 text-slate-500">{item.text}</p></div></div></div>)}</div></Panel><Panel className="p-5"><div className="flex gap-3"><AlertTriangle className="h-5 w-5 text-amber-600"/><div><h3 className="font-black text-slate-950">Portée du contrôle</h3><p className="mt-2 text-xs font-medium leading-6 text-slate-500">Une règle active influence la lecture de préparation existante. Cette surface ne prétend pas scanner automatiquement le texte.</p></div></div></Panel></aside></div></SubpageShell>
}

function LinkingWorkspace({store,addLink}:{store:SeoStore;addLink:(id:string,title:string)=>void}){
  const total=store.articles.reduce((sum,article)=>sum+article.internalLinks.length,0)
  return <SubpageShell mode="linking"><div className="rounded-2xl border border-sky-200 bg-sky-50 p-4"><div className="flex gap-3"><Link2 className="mt-0.5 h-5 w-5 shrink-0 text-sky-700"/><div><p className="text-sm font-black text-sky-950">Plan de maillage interne</p><p className="mt-1 text-xs font-medium leading-5 text-sky-800">L’action existante ajoute une route au tableau de liens internes du dossier. Elle ne crawle pas le site et ne modifie pas une page publique.</p></div></div></div><section className="grid gap-3 sm:grid-cols-3"><MetricLite label="Liens enregistrés" value={total} detail="dans le portefeuille"/><MetricLite label="Articles sans lien" value={store.articles.filter(article=>article.internalLinks.length===0).length} detail="à structurer" danger/><MetricLite label="Clusters couverts" value={new Set(store.articles.filter(a=>a.internalLinks.length).map(a=>a.cluster)).size} detail="avec maillage enregistré"/></section><Panel className="p-5"><SectionHeading eyebrow="Flux d’autorité" title="Couverture article par article" description="Visualisez les liens actuels, le cluster et l’action de suggestion locale existante."/><div className="mt-5 grid gap-4 xl:grid-cols-2">{store.articles.map(article=><article key={article.id} className="rounded-2xl border border-slate-200 p-5"><div className="flex items-start justify-between gap-4"><div><div className="flex flex-wrap gap-2"><StateBadge status={article.status}/><Badge>{article.cluster||"Sans cluster"}</Badge></div><Link href={`/market-os/seo-blog-workspace/${article.id}`} className="mt-4 block text-lg font-black leading-6 text-slate-950 hover:text-sky-700">{article.title}</Link><p className="mt-2 text-xs font-semibold text-slate-500">{article.primaryKeyword}</p></div><div className="rounded-2xl bg-slate-950 px-4 py-3 text-center text-white"><p className="text-2xl font-black">{article.internalLinks.length}</p><p className="text-[9px] font-extrabold uppercase tracking-wide text-slate-400">liens</p></div></div><div className="mt-5 space-y-2">{article.internalLinks.length?article.internalLinks.map((link,index)=><div key={`${link}-${index}`} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-600"><Link2 className="h-3.5 w-3.5 text-sky-600"/><span className="truncate">{link}</span></div>):<div className="rounded-xl border border-dashed border-amber-300 bg-amber-50 p-3 text-xs font-semibold text-amber-800">Aucun lien interne enregistré.</div>}</div><div className="mt-5 flex flex-wrap justify-end gap-2"><Button href={`/market-os/seo-blog-workspace/${article.id}/edit`}>Modifier les liens</Button><Button onClick={()=>addLink(article.id,article.title)} kind="primary"><Link2 className="h-4 w-4"/> Ajouter la suggestion existante</Button></div></article>)}</div></Panel></SubpageShell>
}

export function SeoSubpage({mode,articleId}:{mode:Mode;articleId?:string}){
  const {store,commit}=useSeoStore()
  const article=articleId?store.articles.find(item=>item.id===articleId):undefined
  const save=(nextArticle:SeoArticle)=>commit(draft=>{const exists=draft.articles.some(item=>item.id===nextArticle.id);draft.articles=exists?draft.articles.map(item=>item.id===nextArticle.id?nextArticle:item):[nextArticle,...draft.articles]},mode==="create"?"create":"save",`${mode==="create"?"Created":"Saved"} ${nextArticle.title}`)
  const remove=(id:string)=>commit(draft=>{draft.articles=draft.articles.filter(item=>item.id!==id);draft.tasks=draft.tasks.filter(task=>task.articleId!==id)},"delete",`Deleted article ${id}`)
  const advance=(id:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,status:nextStatus(item.status),updatedAt:new Date().toISOString()}:item)},"advance",`Advanced article ${id}`)
  const approve=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,status:"approved"}:item)},"approve",`Approved ${title}`)
  const revision=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,status:"draft",notes:`${item.notes}\nRevision requested`.trim()}:item)},"revision",`Revision requested for ${title}`)
  const publish=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,status:"published",publishedDate:todayISO()}:item)},"publish",`Published ${title}`)
  const schedule=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,status:"scheduled"}:item)},"schedule",`Scheduled ${title}`)
  const optimize=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,seoScore:Math.min(100,item.seoScore+5),brandScore:Math.min(100,item.brandScore+3),readability:Math.min(100,item.readability+2)}:item)},"optimize",`Optimized ${title}`)
  const toggleCluster=(cluster:SeoCluster)=>commit(draft=>{draft.clusters=draft.clusters.map(item=>item.id===cluster.id?{...item,status:item.status==="active"?"expanding":"active"}:item)},"cluster",`Updated cluster ${cluster.name}`)
  const toggleRule=(rule:SeoRule)=>commit(draft=>{draft.rules=draft.rules.map(item=>item.id===rule.id?{...item,active:!item.active}:item)},"rule",`Toggled ${rule.title}`)
  const addLink=(id:string,title:string)=>commit(draft=>{draft.articles=draft.articles.map(item=>item.id===id?{...item,internalLinks:[...item.internalLinks,`/market-os/seo-blog-workspace/${item.slug}`]}:item)},"link",`Added internal link to ${title}`)
  const createOnDate=(iso:string)=>{const next={...emptyArticle,id:uid("seo"),title:`SEO article scheduled ${iso}`,slug:`seo-article-${iso}`,scheduledDate:iso,dueDate:iso,owner:"SEO Lead",reviewer:"Brand Lead",primaryKeyword:"",cluster:"Planning",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};save(next)}

  if((mode==="detail"||mode==="edit"||mode==="delete")&&!article)return <ArticleNotFound articleId={articleId}/>
  if(mode==="create")return <SubpageShell mode="create"><ArticleForm onSave={save} submitLabel="Enregistrer l’article"/></SubpageShell>
  if(mode==="edit"&&article)return <SubpageShell mode="edit"><ArticleForm initial={article} onSave={save} submitLabel="Mettre à jour l’article"/></SubpageShell>
  if(mode==="detail"&&article)return <DetailWorkspace article={article} store={store} advance={()=>advance(article.id)}/>
  if(mode==="delete"&&article)return <DeleteWorkspace article={article} onDelete={()=>remove(article.id)}/>
  if(mode==="calendar")return <CalendarWorkspace store={store} onDate={createOnDate}/>
  if(mode==="review")return <ReviewWorkspace store={store} approve={approve} revision={revision}/>
  if(mode==="publishing")return <PublishingWorkspace store={store} publish={publish} schedule={schedule}/>
  if(mode==="optimizer")return <OptimizerWorkspace store={store} optimize={optimize}/>
  if(mode==="clusters")return <ClusterWorkspace store={store} toggle={toggleCluster}/>
  if(mode==="analytics")return <AnalyticsWorkspace store={store}/>
  if(mode==="brand")return <BrandWorkspace store={store} toggle={toggleRule}/>
  if(mode==="linking")return <LinkingWorkspace store={store} addLink={addLink}/>
  return <ArticleNotFound articleId={articleId}/>
}
